content:
:root {
  --color-bg: #f4f6fa;
  --color-surface: #ffffff;
  --color-surface-hover: #f8fafc;
  --color-surface-active: #eef2ff;
  --color-border: #e2e8f0;
  --color-border-focus: #6366f1;
  --color-text-main: #1e293b;
  --color-text-muted: #64748b;
  --color-text-subtle: #94a3b8;
  --color-primary: #4f46e5;
  --color-primary-hover: #4338ca;
  --color-primary-light: #e0e7ff;
  --color-danger: #ef4444;
  --color-danger-hover: #dc2626;
  --color-danger-light: #fee2e2;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -1px rgba(0, 0, 0, 0.04);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -2px rgba(0, 0, 0, 0.03);
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s ease;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "BIZ UDPGothic", Meiryo, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: var(--font-family);
  font-variant-numeric: tabular-nums;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button,
input,
select,
textarea {
  font-family: inherit;
  font-size: inherit;
}

/* =========================================
   レイアウト & 全体コンテナ
   ========================================= */

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 20px 48px;
}

@media (max-width: 640px) {
  .app-container {
    padding: 16px 12px 36px;
  }
}

/* =========================================
   ヘッダー
   ========================================= */

.header {
  margin-bottom: 24px;
  text-align: left;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 10px;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  margin-top: 6px;
}

/* =========================================
   サマリーバナー
   ========================================= */

.summary-banner {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
  margin-bottom: 28px;
}

.summary-item {
  background: var(--color-surface);
  padding: 18px 20px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.summary-item:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.summary-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.summary-value {
  font-size: 1.65rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
}

/* =========================================
   メイングリッド配置
   ========================================= */

.main-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 24px;
  align-items: start;
}

@media (max-width: 960px) {
  .main-grid {
    grid-template-columns: 1fr;
    gap: 20px;
  }
}

/* =========================================
   円グラフカード
   ========================================= */

.chart-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  padding: 24px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

.chart-container {
  width: 100%;
  height: 340px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (max-width: 480px) {
  .chart-container {
    height: 280px;
  }
}

.chart-center-label {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 10;
}

.chart-center-label span:first-child {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--color-text-muted);
  letter-spacing: 0.02em;
}

.chart-center-label span:last-child {
  font-size: 1.45rem;
  font-weight: 800;
  color: var(--color-text-main);
  margin-top: 2px;
  font-variant-numeric: tabular-nums;
}

/* =========================================
   詳細表示カード (ハイライトパネル)
   ========================================= */

.detail-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  padding: 24px;
  margin-top: 24px;
  transition: all var(--transition-normal);
  position: relative;
}

.detail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  gap: 12px;
}

.selected-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 0.95rem;
  font-weight: 600;
  background-color: var(--color-primary-light);
  color: var(--color-primary);
}

.detail-amount {
  font-size: 2.1rem;
  font-weight: 800;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
  margin-bottom: 8px;
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-variant-numeric: tabular-nums;
}

.detail-amount span {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

.detail-ratio {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--color-primary);
  background: var(--color-surface-hover);
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  margin-bottom: 14px;
  font-variant-numeric: tabular-nums;
}

.detail-note {
  font-size: 0.92rem;
  color: var(--color-text-muted);
  background: var(--color-bg);
  padding: 12px 16px;
  border-radius: var(--radius-md);
  line-height: 1.6;
  border-left: 3px solid var(--color-primary);
}

.empty-selection {
  text-align: center;
  padding: 32px 16px;
  color: var(--color-text-subtle);
  font-size: 0.95rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

/* =========================================
   支出一覧リスト
   ========================================= */

.list-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  padding: 24px;
  margin-bottom: 24px;
}

.list-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text-main);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.expense-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 440px;
  overflow-y: auto;
  padding-right: 4px;
}

.expense-list::-webkit-scrollbar {
  width: 6px;
}

.expense-list::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 4px;
}

.expense-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background-color: var(--color-surface);
  cursor: pointer;
  transition: all var(--transition-fast);
  gap: 12px;
}

.expense-item:hover {
  background-color: var(--color-surface-hover);
  border-color: #cbd5e1;
}

.expense-item.active {
  background-color: var(--color-surface-active);
  border-color: var(--color-primary);
  box-shadow: 0 0 0 1px var(--color-primary);
}

.expense-item:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-border-focus);
}

.expense-color-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  flex-shrink: 0;
}

.expense-info {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  min-width: 0;
}

.expense-name {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--color-text-main);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.expense-val {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--color-text-main);
  margin-left: auto;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.expense-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* =========================================
   ボタン & アイコンボタン
   ========================================= */

.icon-btn,
.delete-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  color: var(--color-text-subtle);
  padding: 6px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.icon-btn:hover {
  color: var(--color-text-main);
  background-color: var(--color-border);
}

.delete-btn:hover {
  color: var(--color-danger);
  background-color: var(--color-danger-light);
}

.icon-btn:focus-visible,
.delete-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--color-border-focus);
}

/* =========================================
   新規支出登録フォームカード
   ========================================= */

.form-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  padding: 24px;
}

.form-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text-main);
  margin-bottom: 16px;
}

.form-grid {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

.form-input,
.form-select {
  width: 100%;
  padding: 10px 14px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background-color: var(--color-surface);
  color: var(--color-text-main);
  font-size: 0.95rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input:focus,
.form-select:focus {
  outline: none;
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.15);
}

.form-input::placeholder {
  color: var(--color-text-subtle);
}

.submit-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 12px 18px;
  border-radius: var(--radius-md);
  background-color: var(--color-primary);
  color: #ffffff;
  font-weight: 600;
  font-size: 0.95rem;
  border: none;
  cursor: pointer;
  transition: background-color var(--transition-fast), transform var(--transition-fast);
  margin-top: 4px;
}

.submit-btn:hover {
  background-color: var(--color-primary-hover);
}

.submit-btn:active {
  transform: scale(0.99);
}

.submit-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.4);
}

.submit-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

export interface ExpenseCategory {
  id: string;
  name: string;
  amount: number;
  color: string;
  note: string;
  createdAt?: string;
}

export interface ExpenseFormInput {
  name: string;
  amount: number | '';
  color: string;
  note: string;
}

export interface ExpensePieChartProps {
  items: ExpenseCategory[];
  selectedId: string | null;
  onSelect: (id: string | null) => void;
}

export interface ExpenseDetailProps {
  selectedItem: ExpenseCategory | null;
  totalAmount: number;
  onClearSelection: () => void;
}

import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip } from 'recharts';
import { ExpenseCategory, ExpensePieChartProps } from '../types';

export default function ExpensePieChart({
  items = [],
  selectedId,
  onSelect,
}: ExpensePieChartProps) {
  if (items.length === 0) {
    return (
      <div className="chart-container">
        <div className="empty-selection">
          <p>支出データが登録されていません</p>
        </div>
      </div>
    );
  }

  const totalAmount = items.reduce((sum, item) => sum + item.amount, 0);
  const selectedItem = items.find((item) => item.id === selectedId);

  const handleClick = (data: ExpenseCategory) => {
    if (selectedId === data.id) {
      // 親コンポーネントが null を扱えるよう安全に通知
      (onSelect as (id: string | null) => void)(null);
    } else {
      onSelect(data.id);
    }
  };

  return (
    <div className="chart-container">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Tooltip
            formatter={(val: number) => {
              const ratio =
                totalAmount > 0 ? ((val / totalAmount) * 100).toFixed(1) : '0.0';
              return [`${val.toLocaleString()} 円 (${ratio}%)`, '支出額'];
            }}
            contentStyle={{
              backgroundColor: '#ffffff',
              borderRadius: '8px',
              border: '1px solid #e2e8f0',
              boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.07)',
              fontSize: '0.9rem',
              fontWeight: 500,
            }}
          />
          <Pie
            data={items}
            dataKey="amount"
            nameKey="name"
            cx="50%"
            cy="50%"
            innerRadius={78}
            outerRadius={122}
            paddingAngle={3}
            animationDuration={600}
            onClick={handleClick}
            style={{ cursor: 'pointer' }}
          >
            {items.map((entry) => {
              const isSelected = entry.id === selectedId;
              return (
                <Cell
                  key={entry.id}
                  fill={entry.color}
                  stroke={isSelected ? '#1e293b' : '#ffffff'}
                  strokeWidth={isSelected ? 3 : 1.5}
                  opacity={selectedId ? (isSelected ? 1 : 0.45) : 1}
                />
              );
            })}
          </Pie>
        </PieChart>
      </ResponsiveContainer>

      <div className="chart-center-label">
        <span>{selectedItem ? selectedItem.name : '総支出額'}</span>
        <span>
          {selectedItem
            ? `${selectedItem.amount.toLocaleString()}円`
            : `${totalAmount.toLocaleString()}円`}
        </span>
      </div>
    </div>
  );
}

import { useEffect, useCallback } from 'react';
import { X, Info } from 'lucide-react';
import { ExpenseDetailProps } from '../types';

export default function ExpenseDetail({
  selectedItem,
  totalAmount = 0,
  onClearSelection,
}: ExpenseDetailProps) {
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClearSelection();
      }
    },
    [onClearSelection]
  );

  useEffect(() => {
    if (!selectedItem) return;
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [selectedItem, handleKeyDown]);

  if (!selectedItem) {
    return (
      <div className="detail-card">
        <div className="empty-selection">
          <Info size={28} />
          <p>円グラフの扇形または一覧の項目をクリックすると詳細が表示されます</p>
        </div>
      </div>
    );
  }

  const ratio =
    totalAmount > 0
      ? ((selectedItem.amount / totalAmount) * 100).toFixed(1)
      : '0.0';

  const otherAmount = Math.max(0, totalAmount - selectedItem.amount);
  const dailyAverage = Math.round(selectedItem.amount / 30);

  // HEX/RGB/HSLなど多様なカラー指定に安全に対応する背景透過スタイル
  const badgeBg = `color-mix(in srgb, ${selectedItem.color} 15%, transparent)`;

  return (
    <div className="detail-card">
      <div className="detail-header">
        <span
          className="selected-badge"
          style={{
            backgroundColor: badgeBg,
            color: selectedItem.color,
          }}
        >
          <span
            className="expense-color-dot"
            style={{ backgroundColor: selectedItem.color }}
          />
          {selectedItem.name}
        </span>
        <button
          type="button"
          className="icon-btn"
          onClick={() => onClearSelection()}
          aria-label="選択解除 (Esc)"
          title="Escキーでも閉じられます"
        >
          <X size={18} />
        </button>
      </div>

      <div className="detail-amount">
        {selectedItem.amount.toLocaleString()}
        <span>円</span>
      </div>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', marginBottom: '14px' }}>
        <div className="detail-ratio">全体に占める割合: {ratio}%</div>
        <div className="detail-ratio" style={{ color: 'var(--color-text-muted)' }}>
          その他の支出: {otherAmount.toLocaleString()} 円
        </div>
        <div className="detail-ratio" style={{ color: 'var(--color-text-muted)' }}>
          1日目安: 約{dailyAverage.toLocaleString()} 円/日
        </div>
      </div>

      <div className="detail-note">
        {selectedItem.note ? selectedItem.note : 'メモはありません。'}
      </div>
    </div>
  );
}

