export default function App() {
  const [items, setItems] = useState<ExpenseCategory[]>(INITIAL_EXPENSES);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const nameInputId = useId();
  const amountInputId = useId();
  const colorInputId = useId();
  const noteInputId = useId();

  const [formData, setFormData] = useState<ExpenseFormInput>({
    name: '',
    amount: '',
    color: '#4f46e5',
    note: '',
  });

  const totalAmount = items.reduce((sum, item) => sum + item.amount, 0);
  const selectedItem = items.find((item) => item.id === selectedId) || null;

  // 最も支出割合の大きい項目
  const maxExpenseItem = items.length > 0
    ? [...items].sort((a, b) => b.amount - a.amount)[0]
    : null;

  const handleSelect = (id: string | null) => {
    setSelectedId(id === '' ? null : id);
  };

  const handleDelete = (id: string) => {
    const targetItem = items.find((item) => item.id === id);
    const itemName = targetItem ? `「${targetItem.name}」` : 'この項目';
    if (!window.confirm(`${itemName}を削除してもよろしいですか？`)) {
      return;
    }
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const parsedAmount = Math.floor(Number(formData.amount));
    if (
      !formData.name.trim() ||
      formData.amount === '' ||
      isNaN(parsedAmount) ||
      parsedAmount <= 0
    ) {
      return;
    }

    const newItem: ExpenseCategory = {
      id: `exp-${Date.now()}`,
      name: formData.name.trim(),
      amount: parsedAmount,
      color: formData.color,
      note: formData.note.trim(),
    };

    setItems((prev) => [...prev, newItem]);
    setSelectedId(newItem.id);

    setFormData({
      name: '',
      amount: '',
      color: PRESET_COLORS[(items.length + 1) % PRESET_COLORS.length].value,
      note: '',
    });
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">
          <PieChartIcon size={30} color="#4f46e5" />
          家計支出ダッシュボード
        </h1>
        <p className="header-subtitle">
          円グラフの扇形や項目をクリックして支出の内訳と比率を詳しくチェックできます
        </p>
      </header>

      {/* サマリーバナー */}
      <section className="summary-banner">
        <div className="summary-item">
          <span className="summary-label">今月の総支出</span>
          <span className="summary-value">{totalAmount.toLocaleString()} 円</span>
        </div>
        <div className="summary-item">
          <span className="summary-label">登録カテゴリ数</span>
          <span className="summary-value">{items.length} 項目</span>
        </div>
        <div className="summary-item">
          <span className="summary-label">最大支出項目</span>
          <span className="summary-value">
            {maxExpenseItem
              ? `${maxExpenseItem.name} (${maxExpenseItem.amount.toLocaleString()}円)`
              : '-'}
          </span>
        </div>
      </section>

      {/* メインレイアウト */}
      <main className="main-grid">
        {/* 左側: 円グラフ & 詳細情報パネル */}
        <div className="chart-card">
          <ExpensePieChart
            items={items}
            selectedId={selectedId}
            onSelect={handleSelect}
          />
          <ExpenseDetail
            selectedItem={selectedItem}
            totalAmount={totalAmount}
            onClearSelection={() => setSelectedId(null)}
          />
        </div>

        {/* 右側: 支出項目一覧 & 新規登録フォーム */}
        <div>
          <div className="list-card">
            <h2 className="list-title">
              支出内訳リスト
              <span style={{ fontSize: '0.85rem', color: '#64748b', fontWeight: 500 }}>
                {items.length} 件
              </span>
            </h2>
            <ul className="expense-list">
              {items.map((item) => {
                const isActive = item.id === selectedId;
                const ratio =
                  totalAmount > 0
                    ? ((item.amount / totalAmount) * 100).toFixed(1)
                    : '0.0';

                return (
                  <li
                    key={item.id}
                    className={isActive ? 'expense-item active' : 'expense-item'}
                    role="button"
                    tabIndex={0}
                    onClick={() => handleSelect(item.id)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        handleSelect(item.id);
                      }
                    }}
                  >
                    <span
                      className="expense-color-dot"
                      style={{ backgroundColor: item.color }}
                    />
                    <div className="expense-info">
                      <span className="expense-name">{item.name}</span>
                      <span
                        style={{
                          fontSize: '0.82rem',
                          color: '#64748b',
                          marginLeft: '4px',
                        }}
                      >
                        {ratio}%
                      </span>
                    </div>
                    <span className="expense-val">
                      {item.amount.toLocaleString()} 円
                    </span>
                    <div className="expense-actions">
                      <button
                        type="button"
                        className="delete-btn"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDelete(item.id);
                        }}
                        aria-label={`${item.name}を削除`}
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </li>
                );
              })}
            </ul>
          </div>

          <div className="form-card">
            <h2 className="form-title">支出項目の追加</h2>
            <form onSubmit={handleSubmit} className="form-grid">
              <div className="form-group">
                <label htmlFor={nameInputId} className="form-label">
                  項目名 *
                </label>
                <input
                  id={nameInputId}
                  type="text"
                  className="form-input"
                  placeholder="例: ガソリン代、書籍代"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor={amountInputId} className="form-label">
                  金額 (円) *
                </label>
                <input
                  id={amountInputId}
                  type="number"
                  className="form-input"
                  placeholder="例: 5000"
                  min="1"
                  step="1"
                  value={formData.amount}
                  onChange={(e) => {
                    const val = e.target.value;
                    setFormData({
                      ...formData,
                      amount: val === '' ? '' : Math.floor(Number(val)),
                    });
                  }}
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor={colorInputId} className="form-label">
                  カラーテーマ
                </label>
                <select
                  id={colorInputId}
                  className="form-select"
                  value={formData.color}
                  onChange={(e) =>
                    setFormData({ ...formData, color: e.target.value })
                  }
                >
                  {PRESET_COLORS.map((color) => (
                    <option key={color.value} value={color.value}>
                      {color.label}
                    </option>
                  ))}
                </select>
              </div>

              <div className="form-group">
                <label htmlFor={noteInputId} className="form-label">
                  メモ・内訳 (任意)
                </label>
                <input
                  id={noteInputId}
                  type="text"
                  className="form-input"
                  placeholder="例: 週末のドライブ用、月2回"
                  value={formData.note}
                  onChange={(e) =>
                    setFormData({ ...formData, note: e.target.value })
                  }
                />
              </div>

              <button
                type="submit"
                className="submit-btn"
                disabled={!formData.name.trim() || formData.amount === ''}
              >
                <Plus size={18} />
                支出項目を追加
              </button>
            </form>
          </div>
        </div>
      </main>
    </div>
  );
}
